import React, { useState } from "react";
import * as emailjs from "emailjs-com";
import "./style.css";
import { Helmet, HelmetProvider } from "react-helmet-async";
import { meta, contactConfig } from "../../content_option";
import { Container, Row, Col } from "react-bootstrap";
import { useLanguage } from "../../i18n/LanguageContext";
import {
  FaEnvelope,
  FaPhone,
  FaMapMarkerAlt,
  FaClock,
  FaCheckCircle,
  FaUsers,
  FaTrophy,
  FaPaperPlane,
} from "react-icons/fa";

export const ContactUs = () => {
  const { t, language } = useLanguage();
  const [formData, setFormdata] = useState({
    email: "",
    name: "",
    company: "",
    message: "",
    loading: false,
    show: false,
    alertmessage: "",
    variant: "",
  });

  const handleSubmit = (e) => {
    e.preventDefault();
    setFormdata((prev) => ({ ...prev, loading: true, show: false }));

    const templateParams = {
      from_name: formData.email,
      user_name: formData.name,
      user_company: formData.company,
      to_name: contactConfig.YOUR_EMAIL,
      message: formData.message,
    };

    emailjs
      .send(
        contactConfig.YOUR_SERVICE_ID,
        contactConfig.YOUR_TEMPLATE_ID,
        templateParams,
        contactConfig.YOUR_USER_ID
      )
      .then(
        () => {
          setFormdata({
            email: "",
            name: "",
            company: "",
            message: "",
            loading: false,
            alertmessage: t("contact.success"),
            variant: "success",
            show: true,
          });
        },
        () => {
          setFormdata((prev) => ({
            ...prev,
            loading: false,
            alertmessage: t("contact.error"),
            variant: "danger",
            show: true,
          }));
        }
      );
  };

  const handleChange = (e) => {
    setFormdata({ ...formData, [e.target.name]: e.target.value });
  };

  const infoItems = [
    {
      icon: <FaEnvelope />,
      label: t("contact.info.email"),
      value: contactConfig.YOUR_EMAIL,
      href: `mailto:${contactConfig.YOUR_EMAIL}`,
    },
    {
      icon: <FaPhone />,
      label: t("contact.info.phone"),
      value: contactConfig.YOUR_FONE,
      href: `tel:${contactConfig.YOUR_FONE}`,
    },
    {
      icon: <FaMapMarkerAlt />,
      label: t("contact.info.location"),
      value: t("contact.info.locationValue"),
    },
    {
      icon: <FaClock />,
      label: t("contact.info.schedule"),
      value: t("contact.info.scheduleValue"),
    },
  ];

  const features = [
    {
      icon: <FaCheckCircle />,
      title: t("contact.features.consultation.title"),
      description: t("contact.features.consultation.description"),
    },
    {
      icon: <FaUsers />,
      title: t("contact.features.team.title"),
      description: t("contact.features.team.description"),
    },
    {
      icon: <FaTrophy />,
      title: t("contact.features.results.title"),
      description: t("contact.features.results.description"),
    },
  ];

  const pageTitle = language === 'pt'
    ? "Contato | Consultoria de IA - Tyber.io"
    : "Contact | AI Consulting - Tyber.io";

  const pageDescription = language === 'pt'
    ? "Entre em contato com a Tyber.io para consultoria de IA. Agende uma consulta gratuita sobre machine learning, NLP, visão computacional e automação inteligente."
    : "Contact Tyber.io for AI consulting. Schedule a free consultation about machine learning, NLP, computer vision, and intelligent automation.";

  return (
    <HelmetProvider>
      <section className="contact-page" itemScope itemType="https://schema.org/ContactPage">
        <Helmet>
          <html lang={language === 'pt' ? 'pt-BR' : 'en'} />
          <title>{pageTitle}</title>
          <meta name="description" content={pageDescription} />
          <link rel="canonical" href="https://tyber.io/contact" />
          <meta property="og:title" content={pageTitle} />
          <meta property="og:description" content={pageDescription} />
          <meta property="og:url" content="https://tyber.io/contact" />
          <meta property="og:type" content="website" />
          <meta name="twitter:title" content={pageTitle} />
          <meta name="twitter:description" content={pageDescription} />
        </Helmet>

        {/* ── Hero ─────────────────────────────────────────────────── */}
        <div className="contact-hero">
          <Container>
            <div className="contact-hero__badge">
              <span className="badge-dot"></span>
              <span>{t("contact.badge")}</span>
            </div>
            <h1 className="contact-hero__title">
              <span className="gradient-text">{t("contact.title")}</span>
            </h1>
            <p className="contact-hero__subtitle">{t("contact.subtitle")}</p>

            <div className="contact-hero__stats">
              <div className="contact-stat">
                <span className="contact-stat__value">&lt;24h</span>
                <span className="contact-stat__label">
                  {t("contact.stats.responseTime.label")}
                </span>
              </div>
              <div className="contact-stat">
                <span className="contact-stat__value">
                  {t("contact.stats.consultation.value")}
                </span>
                <span className="contact-stat__label">
                  {t("contact.stats.consultation.label")}
                </span>
              </div>
              <div className="contact-stat">
                <span className="contact-stat__value">98%</span>
                <span className="contact-stat__label">
                  {t("contact.stats.satisfaction.label")}
                </span>
              </div>
            </div>
          </Container>
        </div>

        {/* ── Body ─────────────────────────────────────────────────── */}
        <div className="contact-body">
          <Container>
            <Row className="contact-main-row">
              {/* ── Info Panel ──────────────────────────────────── */}
              <Col lg={5} className="mb-5 mb-lg-0">
                <div className="contact-info">
                  {/* Contact details */}
                  <div className="contact-info__card">
                    {infoItems.map((item, i) => (
                      <div key={i} className="contact-info__item">
                        <div className="contact-info__icon">{item.icon}</div>
                        <div className="contact-info__text">
                          <span className="contact-info__label">
                            {item.label}
                          </span>
                          {item.href ? (
                            <a
                              href={item.href}
                              className="contact-info__value contact-info__link"
                            >
                              {item.value}
                            </a>
                          ) : (
                            <span className="contact-info__value">
                              {item.value}
                            </span>
                          )}
                        </div>
                      </div>
                    ))}
                  </div>

                  {/* Feature cards */}
                  <div className="contact-features">
                    {features.map((f, i) => (
                      <div key={i} className="contact-feature">
                        <div className="contact-feature__icon">{f.icon}</div>
                        <div className="contact-feature__text">
                          <h4 className="contact-feature__title">{f.title}</h4>
                          <p className="contact-feature__desc">
                            {f.description}
                          </p>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              </Col>

              {/* ── Form ─────────────────────────────────────────── */}
              <Col lg={7}>
                <div className="contact-form__card">
                  <div className="contact-form__header">
                    <h3 className="contact-form__title">
                      {t("contact.formTitle")}
                    </h3>
                  </div>

                  <form onSubmit={handleSubmit} className="contact-form">
                    <Row>
                      <Col md={6}>
                        <div className="contact-form__group">
                          <label className="contact-form__label">
                            {t("contact.form.name.label")}
                          </label>
                          <input
                            className="contact-form__input"
                            id="name"
                            name="name"
                            placeholder={t("contact.form.name.placeholder")}
                            value={formData.name}
                            type="text"
                            required
                            onChange={handleChange}
                          />
                        </div>
                      </Col>
                      <Col md={6}>
                        <div className="contact-form__group">
                          <label className="contact-form__label">
                            {t("contact.form.email.label")}
                          </label>
                          <input
                            className="contact-form__input"
                            id="email"
                            name="email"
                            placeholder={t("contact.form.email.placeholder")}
                            type="email"
                            value={formData.email}
                            required
                            onChange={handleChange}
                          />
                        </div>
                      </Col>
                    </Row>

                    <div className="contact-form__group">
                      <label className="contact-form__label">
                        {t("contact.form.company.label")}
                      </label>
                      <input
                        className="contact-form__input"
                        id="company"
                        name="company"
                        placeholder={t("contact.form.company.placeholder")}
                        type="text"
                        value={formData.company}
                        onChange={handleChange}
                      />
                    </div>

                    <div className="contact-form__group">
                      <label className="contact-form__label">
                        {t("contact.form.message.label")}
                      </label>
                      <textarea
                        className="contact-form__input contact-form__textarea"
                        id="message"
                        name="message"
                        placeholder={t("contact.form.message.placeholder")}
                        rows="6"
                        value={formData.message}
                        onChange={handleChange}
                        required
                      />
                    </div>

                    <button
                      className="contact-form__submit"
                      type="submit"
                      disabled={formData.loading}
                    >
                      {formData.loading ? (
                        <span className="contact-form__loading">
                          <span className="contact-spinner" />
                          {t("contact.form.sending")}
                        </span>
                      ) : (
                        <span className="contact-form__submit-inner">
                          <FaPaperPlane />
                          {t("contact.form.submit")}
                        </span>
                      )}
                    </button>

                    {formData.show && (
                      <div
                        className={`contact-alert contact-alert--${formData.variant}`}
                      >
                        <span>{formData.alertmessage}</span>
                        <button
                          type="button"
                          className="contact-alert__close"
                          onClick={() =>
                            setFormdata((prev) => ({ ...prev, show: false }))
                          }
                        >
                          ✕
                        </button>
                      </div>
                    )}
                  </form>
                </div>
              </Col>
            </Row>
          </Container>
        </div>
      </section>

      {formData.loading && <div className="loading-bar" />}
    </HelmetProvider>
  );
};
